/* Platform showcase — distinct editorial composition rather than five uniform cards */
.cs-platforms{background:linear-gradient(180deg,#f4f9ff 0%,#fff 90%);position:relative}
.cs-platforms__heading{margin-bottom:42px}
.cs-gradient-text{color:#2879f5}
.cs-platforms__showcase{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:22px;align-items:stretch}
.cs-platform-feature{position:relative;display:flex;min-height:480px;border-radius:28px;padding:40px;overflow:hidden;background:radial-gradient(circle at 75% 65%,#285ed4 0%,transparent 43%),linear-gradient(140deg,#0c2144 0%,#102f72 60%,#123e8c 100%);color:#fff;box-shadow:0 24px 60px #173f7b20;isolation:isolate}
.cs-platform-feature:before{content:'';position:absolute;inset:0;background:linear-gradient(transparent 96%,#ffffff0c 97%),linear-gradient(90deg,transparent 96%,#ffffff0c 97%);background-size:42px 42px;mask-image:linear-gradient(90deg,transparent,#000);pointer-events:none}
.cs-platform-feature__copy{position:relative;z-index:2;max-width:350px;align-self:flex-start}
.cs-platform-feature__tag{display:inline-flex;align-items:center;gap:8px;font-size:10px;font-weight:800;letter-spacing:.11em;color:#9ac9ff;background:#ffffff14;border:1px solid #ffffff25;border-radius:100px;padding:10px 14px}
.cs-platform-feature h3{font-size:clamp(43px,4vw,67px);letter-spacing:-.06em;margin:30px 0 10px;line-height:1.1}
.cs-platform-feature p{font-size:15px;line-height:1.8;color:#c7d9f5;max-width:310px}
.cs-platform-feature__link{display:inline-flex;align-items:center;gap:10px;margin-top:25px;font-weight:800;font-size:13px;color:white}
.cs-platform-feature__art{position:absolute;inset:0;pointer-events:none}
.cs-platform-feature__halo{position:absolute;width:380px;height:380px;right:-70px;bottom:-130px;border:1px solid #8fc3ff45;border-radius:50%;box-shadow:0 0 0 35px #7caeff0b,0 0 0 85px #7caeff09}
.cs-platform-feature__cube{position:absolute;display:grid;place-items:center;border:1px solid #94ceff9c;background:linear-gradient(140deg,#5cb7ffeb,#2264e4d9 45%,#112e87);box-shadow:inset 0 2px 20px #ffffff55,0 22px 50px #00103499,0 0 45px #2f80ff77;color:white;border-radius:24px;transform:rotate(-13deg) skew(3deg,3deg)}
.cs-platform-feature__cube--main{width:154px;height:154px;right:72px;bottom:80px;font-size:68px}
.cs-platform-feature__cube--small{width:92px;height:92px;right:20px;bottom:240px;font-size:36px;transform:rotate(12deg)}
.cs-platform-feature__cube--third{width:72px;height:72px;right:250px;bottom:38px;font-size:27px;transform:rotate(14deg)}
.cs-platforms__right{display:grid;grid-template-rows:auto 1fr;gap:16px}
.cs-platforms__intro{display:flex;align-items:center;gap:17px;padding:21px 24px;border-radius:20px;background:#eaf3ff;border:1px solid #d4e7ff}
.cs-platforms__intro-icon{display:grid;place-items:center;flex:none;width:48px;height:48px;border-radius:15px;background:#2f80ff;color:white;font-size:25px}
.cs-platforms__intro strong{font-size:16px}.cs-platforms__intro p{font-size:12px;color:#68809d;margin:6px 0 0;line-height:1.5}
.cs-platforms__tiles{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}
.cs-platform-tile{position:relative;display:flex;flex-direction:column;align-items:flex-start;min-height:166px;padding:23px;border-radius:20px;border:1px solid #e0eaf7;background:#fff;box-shadow:0 8px 25px #15417c07;transition:transform .2s,box-shadow .2s,border-color .2s}
.cs-platform-tile:hover{transform:translateY(-5px);box-shadow:0 18px 38px #15417c16;border-color:#9cc5ff}
.cs-platform-tile__logo{height:49px;display:flex;align-items:center;font-size:29px;font-weight:900;letter-spacing:-.06em;margin-bottom:auto}
.cs-platform-tile--bitrix .cs-platform-tile__logo{color:#2696ed}.cs-platform-tile--amo .cs-platform-tile__logo{color:#0c3879;font-size:25px;font-style:italic}.cs-platform-tile--amo .cs-platform-tile__logo span{color:#269af0}.cs-platform-tile--sber .cs-platform-tile__logo{color:#20b45e;font-size:35px}.cs-platform-tile--other .cs-platform-tile__logo{color:#6a7fe5;font-size:35px}
.cs-platform-tile strong{font-size:17px;margin-top:12px}.cs-platform-tile small{color:#8092a8;font-size:12px;margin-top:6px}.cs-platform-tile__arrow{position:absolute;right:21px;top:21px;color:#9bb4d4}
@media(max-width:1000px){.cs-platforms__showcase{grid-template-columns:1fr}.cs-platform-feature{min-height:390px}.cs-platform-feature__cube--main{right:15%;bottom:65px}.cs-platforms__right{grid-template-rows:auto auto}.cs-platforms__tiles{grid-template-columns:repeat(4,minmax(0,1fr))}.cs-platform-tile{min-height:170px}}
@media(max-width:700px){.cs-platforms__tiles{grid-template-columns:repeat(2,minmax(0,1fr))}.cs-platform-feature{padding:27px;min-height:470px}.cs-platform-feature__copy{max-width:290px}.cs-platform-feature__cube--main{right:20%;bottom:36px;width:120px;height:120px;font-size:52px}.cs-platform-feature__cube--small{right:8%;bottom:148px;width:65px;height:65px;font-size:25px}.cs-platform-feature__cube--third{right:55%;bottom:22px;width:55px;height:55px;font-size:22px}.cs-platforms__intro{padding:17px}.cs-platforms__intro strong{font-size:14px}.cs-platform-tile{padding:18px;min-height:155px}.cs-platform-tile strong{font-size:15px}}

/* Services showcase: feature-led editorial composition */
.cs-services{background:linear-gradient(180deg,#f5f9ff 0%,#fff 100%)}
.cs-services__heading h2{max-width:790px}.cs-services__accent{color:#2f80ff}
.cs-services__layout{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);gap:22px;align-items:stretch}
.cs-services__spotlight{position:relative;overflow:hidden;min-height:625px;border-radius:28px;background:radial-gradient(circle at 65% 85%,#225dd1 0%,transparent 46%),linear-gradient(145deg,#081b36,#123e83);color:#fff;padding:40px;isolation:isolate;box-shadow:0 24px 65px #123a791d}
.cs-services__spotlight:after{content:'';position:absolute;inset:0;background:linear-gradient(transparent 97%,#ffffff09 98%),linear-gradient(90deg,transparent 97%,#ffffff09 98%);background-size:38px 38px;mask-image:linear-gradient(180deg,transparent 25%,#000);pointer-events:none}
.cs-services__spotlight-copy{position:relative;z-index:3}.cs-services__spotlight-tag{display:inline-flex;align-items:center;gap:8px;padding:9px 13px;border-radius:100px;background:#ffffff14;border:1px solid #ffffff28;font-size:10px;font-weight:800;letter-spacing:.12em;color:#a8d4ff}
.cs-services__spotlight h3{font-size:clamp(31px,3vw,44px);line-height:1.15;letter-spacing:-.045em;margin:24px 0 14px}.cs-services__spotlight h3 span{color:#80baff}.cs-services__spotlight p{font-size:14px;line-height:1.8;color:#b8cce8;max-width:370px}
.cs-services__spotlight-link{display:inline-flex;align-items:center;gap:10px;margin-top:19px;color:#fff;font-weight:800;font-size:13px}
.cs-services__art{position:absolute;bottom:5px;left:0;width:100%;height:320px;z-index:1}
.cs-services__art-glow{position:absolute;width:350px;height:240px;left:50%;top:10%;transform:translateX(-50%);background:#268bff;opacity:.45;filter:blur(65px)}
.cs-services__art-grid{position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 36px,#88bfff13 37px),repeating-linear-gradient(90deg,transparent 0 36px,#88bfff13 37px);transform:perspective(400px) rotateX(35deg);mask-image:linear-gradient(0deg,#000,transparent)}
.cs-services__art-center{position:absolute;left:50%;top:52%;transform:translate(-50%,-50%) rotate(-8deg);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:7px;width:140px;height:140px;border-radius:30px;background:linear-gradient(140deg,#65c9ff,#2269e9 55%,#123389);border:1px solid #b3edff;box-shadow:inset 0 2px 18px #ffffff75,0 25px 45px #00102c99,0 0 50px #3a9cff77;color:white;font-size:52px}
.cs-services__art-center span{font-size:16px;font-weight:900;letter-spacing:.09em}
.cs-services__art-card{position:absolute;display:flex;align-items:center;gap:9px;padding:13px 15px;border-radius:13px;border:1px solid #b8dfff6b;background:linear-gradient(135deg,#ffffffec,#dceeffec);box-shadow:0 18px 40px #001c5070;color:#17477c;font-size:12px;font-weight:800;z-index:2}
.cs-services__art-card :deep(svg){font-size:22px;color:#2f80ff}
.cs-services__art-card--one{top:8%;left:9%;transform:rotate(-9deg)}.cs-services__art-card--two{top:8%;right:7%;transform:rotate(8deg)}.cs-services__art-card--three{bottom:5%;right:12%;transform:rotate(-5deg)}
.cs-services__art-line{position:absolute;height:2px;background:linear-gradient(90deg,#60bbff,#a8efff);box-shadow:0 0 14px #5aaeff;opacity:.75;transform-origin:left}
.cs-services__art-line--a{width:29%;left:27%;top:27%;transform:rotate(35deg)}.cs-services__art-line--b{width:27%;left:57%;top:47%;transform:rotate(-44deg)}.cs-services__art-line--c{width:27%;left:58%;top:63%;transform:rotate(30deg)}
.cs-services__cards{display:grid;grid-template-columns:1fr;gap:12px}
.cs-service{display:flex;align-items:center;gap:19px;min-height:113px;padding:19px 22px;border:1px solid #dce8f5;border-radius:18px;background:#fff;position:relative;text-decoration:none;transition:transform .2s,border-color .2s,box-shadow .2s}
.cs-service:hover{transform:translateX(5px);border-color:#9bc7ff;box-shadow:0 12px 35px #1d5fa811}
.cs-service__icon{display:grid;place-items:center;width:58px;height:58px;flex:none;border-radius:17px;background:linear-gradient(145deg,#eaf4ff,#dbeaff);color:#2f80ff;font-size:27px}
.cs-service__body{flex:1;min-width:0}.cs-service__number{font-size:9px;font-weight:800;letter-spacing:.12em;color:#91a6c0}.cs-service h3{font-size:18px;margin:5px 0 4px;letter-spacing:-.025em}.cs-service p{font-size:12px;line-height:1.55;color:#7588a0;max-width:450px;margin:0}
.cs-service__arrow{position:static;flex:none;display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:#f0f6ff;color:#2f80ff;font-size:18px}
